// Command hoistre writes the Go file it is given, as generated by
// go-jsonschema, with each regular expression compiled once.
//
//	hoistre -p <package> -o <out.go> <in.go>
package main

import (
	"flag"
	"fmt"
	"os"

	"github.com/sdboyer/thema/internal/bench/hoistre"
)

func main() {
	pkg := flag.String("p", "", "package name of the file written")
	out := flag.String("o", "", "file to write")
	flag.Parse()
	if *pkg == "" || *out == "" || flag.NArg() != 1 {
		fmt.Fprintln(os.Stderr, "usage: hoistre -p <package> -o <out.go> <in.go>")
		os.Exit(2)
	}
	src, err := os.ReadFile(flag.Arg(0))
	if err == nil {
		src, err = hoistre.Hoist(src, *pkg)
	}
	if err == nil {
		err = os.WriteFile(*out, src, 0o644) //nolint:gosec // generated source, not a secret
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
